/**
 * 文档渲染器：模板 + token 表 → 两份对外文档。**纯函数、import-free**（理由见 `docTokens.ts` 顶部）。
 *
 * 设计约束（长期维护）：
 *   1. **未定义的 token 直接抛**，不做"原样留着"这种静默降级——模板打错一个字就得当场知道；
 *   2. 渲染结果末尾归一成单个换行，避免"多一个空行"变成一次噪音 diff；
 *   3. 生成产物开头固定一行"勿手改"，闸用**渲染结果 == 已提交文档**做等式核对。
 *
 * ⚠️ 定界符用 `<<…>>` 而**不是** `{{…}}`：正文里有酒馆自己的宏（`{{char}}` / `{{user}}` /
 * `{{personality}}` / `{{scenario}}`），双花括号会撞车——第一版就是 `{{…}}`，渲染时当场报
 * "未登记的 token：char, user, personality, scenario"。`<<…>>` 在这套正文里不出现，所以不用转义。
 */

/** 两份文档的产物路径与模板路径（唯一登记处：生成器与闸都读这里） */
export const DOC_FILES = [
  { lang: 'zh', doc: 'docs/tavern-compatibility.md', template: 'tests/fixtures/tavern-docs/tavern-compatibility.zh.md' },
  { lang: 'en', doc: 'docs/tavern-compatibility.en.md', template: 'tests/fixtures/tavern-docs/tavern-compatibility.en.md' },
] as const

export type DocLang = (typeof DOC_FILES)[number]['lang']

/** 生成产物开头那行"勿手改"声明 */
export const HEADERS: Record<DocLang, string> = {
  zh: '<!-- 由 pnpm generate:tavern-docs 生成（数字与源码引用来自 tests/fixtures/tavern-docs/docTokens.ts），请勿手工修改。 -->',
  en: '<!-- Generated by pnpm generate:tavern-docs (numbers and source references come from tests/fixtures/tavern-docs/docTokens.ts). Do not edit by hand. -->',
}

/** 把模板里的 `<<token>>` 全部替换掉；有未知 token 或残留定界符就抛 */
export function renderTemplate(template: string, tokenMap: Map<string, string>, name = 'template'): string {
  const unknown = new Set<string>()
  const rendered = template.replace(/<<([^<>]*)>>/g, (match, rawId: string) => {
    const id = rawId.trim()
    if (!tokenMap.has(id)) {
      unknown.add(id)
      return match
    }
    return tokenMap.get(id) as string
  })
  if (unknown.size) {
    throw new Error(`${name}: 模板里有未登记的 token：${[...unknown].sort().join(', ')}（登记处在 tests/fixtures/tavern-docs/docTokens.ts）`)
  }
  const leftover = /<<|>>/.exec(rendered)
  if (leftover) {
    const line = rendered.slice(0, leftover.index).split('\n').length
    throw new Error(`${name}: 第 ${line} 行有没配对的 <<（token 必须写成一整对 <<id>>）`)
  }
  return rendered
}

/** 渲染一份文档（含"勿手改"声明，末尾恰好一个换行） */
export function renderDoc(lang: DocLang, template: string, tokenMap: Map<string, string>): string {
  const header = HEADERS[lang]
  if (!header) throw new Error(`没有 ${lang} 的生成声明`)
  // ⚠️ 换行归一（2026-10-07 独立评估 P0-2）：产物 `docs/tavern-compatibility*.md` 用 `.gitattributes`
  // 钉死 LF，而**模板**的换行由检出决定（Git for Windows 默认 `core.autocrlf=true` ⇒ 工作区里是 CRLF）。
  // 第一版只钉了产物、没归一模板，于是模板里的 `\r` 原样进了渲染结果、与 LF 产物逐字比对 ⇒
  // `check:tavern-docs`（在 `pnpm build` 里）在 Windows 上误报"已过期"。同一类坑上游修过一次
  // （`97a1b7d`），那次也只修了输出侧。这里在**输入端**归一，与检出配置无关。
  const normalized = template.replace(/\r\n/g, '\n')
  return `${header}\n\n${renderTemplate(normalized, tokenMap, `${lang} 模板`).trimEnd()}\n`
}

/** 模板里用到的所有 token id（闸用它查"有没有登记了却没用的死 token"） */
export function usedTokens(...templates: string[]): Set<string> {
  const ids = new Set<string>()
  for (const template of templates) {
    for (const match of template.matchAll(/<<([^<>]*)>>/g)) ids.add((match[1] ?? '').trim())
  }
  return ids
}
